SourceCode.Declaration:
/// <summary>
/// MPJ-21310 DEVOPS 34618
/// Responsible for dealing with item substitution logic.
/// </summary>
class METSalesItemSubstitution
{
    // ***** WIP *****

    // NB messages for the 'verbose' log will not be labelled as they're intended
    // for internal debugging/documentation use only.
    
    // - If an 'Always' sub was applied, should we check for the other types
    //   at point of reservation?
    // - Check result of item/site specific settings
    // - Data entity
    // - Labels and BP
    // - Qty conversion for line copy/replacement not picking up correct unit(s).
    // - Prompt when updating date-effective substitute entry 
    // - Cleanup job on verbose log entries

    SalesLine                               salesLine;
    METSalesLine                            metSalesLine;
    InventDim                               inventDim;
    SalesTable                              salesTable;

    METSalesItemSubstitutionEventSource     eventSource;
    boolean                                 interactive;  
    boolean                                 verboseLogging;
    UserConnection                          verboseLogConnection;
    METSalesItemSubstitutionAccountRelation substitutionGroup;
    boolean                                 itemReplaced;


}

Method.Source:
    /// <summary>
    /// Perform substitute checks/replacements.
    /// </summary>
    /// <returns>True if validation result is ok. (Not necessarily whether a replacement was made)</returns>
    public boolean run()
    {
        boolean ret;

        if(!CustParameters::find().METSubstitutionEnabled)
        {
            // Subs not enabled at legal-entity level.
            return true;
        }

        if(!salesLine.metSubstitutionsActive())
        {
            // Subs not applicable to this line.
            return true;
        }

        if(CustParameters::find().METSubstitutionVerboseLogging)
        {
            this.verboseLogging         = true;
            this.verboseLogConnection   = new UserConnection();
            if(!metSalesLine.SubstitutionVerboseLogReference)
            {
                metSalesLine.SubstitutionVerboseLogReference = newGuid();
            }
        }

        // *** tbd, may define a separate 'substitution group'. For now 
        // we're using the customer group.
        substitutionGroup = salesTable.custTable_CustAccount().CustGroup;   

        this.verboseInfo(funcName(), strFmt('Checking for substitutes, event source %1', this.eventSource));
        this.verboseInfo(funcName(), strFmt('Item %1, Inventory site %2',
            salesLine.ItemId, 
            salesTable.InventSiteId));

        if(this.checkNoAlternativeExists())
        {
            this.verboseInfo(funcName(), strFmt('"%1" entry exists. No further substitute checks will be made.',
                METSalesItemSubstitutionCode::NoAlternative));
            return true;
        }
        else
        {
            this.verboseInfo(funcName(), 'No matching (No alternative) entry exists');
        }

        ttsbegin;

        switch(this.eventSource)
        {
            case METSalesItemSubstitutionEventSource::Creation:
                ret = this.checkSalesLineAtCreation();
                break;
            case METSalesItemSubstitutionEventSource::Reservation:
                ret = this.checkSalesLineAtReservation();
                break;
            default:
                throw error(strFmt("Unknown substitution event source '%1' in %2",
                    this.eventSource,
                    funcName()));
        }

        if(ret)
        {
            if(itemReplaced)
            {
                salesLine.itemIdChanged();
                this.updateQuantity();
               
                // ** TODO "Product number" not refreshing on form.

                this.verboseInfo(funcName(), strFmt('Item "%1" replaced with "%2"',
                    metSalesLine.SubstituteOriginalItemID,
                    metSalesLine.SubstituteReplacementItemID));
            }
            else
            {
                this.verboseInfo(funcName(), 'No replacement has been made');
            }
        }

        ttscommit;

        return true;
    }

    /// <summary>
    /// Check if any "No alternative" entries exist.
    /// </summary>
    /// <returns>Result</returns>
    protected boolean checkNoAlternativeExists()
    {
        METSalesItemSubstitute noAltSub = this.findSalesItemSubstitute(
            salesLine.ItemId, 
            METSalesItemSubstitutionCode::NoAlternative);

        if(noAltSub)
        {
            this.verboseInfo(funcName(), strFmt('(%1) entry exists',
                noAltSub));
            return true;            
        }
        return false;
    }

    /// <summary>
    /// Check / apply substitutes at point of order line reservation
    /// </summary>
    /// <returns>Validation result.</returns>
    protected boolean checkSalesLineAtReservation()
    {
        boolean ret = true;

        if(!salesLine.selectForUpdate())
        {
            throw error("Sales line must be selected for update");
        }

        if(!salesLine.InventTransId)
        {
            throw error(strFmt("%1 can only be called when the sales order line has already been saved",
                funcName()));
        }

        this.verboseInfo(funcName(), strFmt('Checking line item %1 (Lot ID %2)',
            salesLine.ItemId,
            salesLine.InventTransId));

        if(metSalesLine.SubstitutionType != METSalesItemSubstitutionType::None)
        {
            // Sub already applied.
            // TODO confirm whether reservation checks should be made in addition
            // to any replacements made at the point of line creation.
            this.verboseInfo(funcName(), 'Line has already had replacements applied');
            return true;
        }

        Qty onHandQty = this.queryOnHandQty(salesLine.ItemId, inventDim);
        if(onHandQty < salesLine.QtyOrdered)
        {
            // Insufficient qty ("OOS")
            this.verboseInfo(funcName(), strFmt('On-hand qty of %1 is less than ordered quantity of %2',
                onHandQty,
                salesLine.QtyOrdered));
            
            METSalesItemSubstitute itemSubNever = this.findSalesItemSubstitute(
                salesLine.ItemId, 
                METSalesItemSubstitutionCode::Never);
            if(itemSubNever)
            {
                this.verboseInfo(funcName(), '"Never" substitution entry found');
                this.updateSalesLineFromSalesItemSubstitute(itemSubNever, false);                
                itemReplaced = false;
            }
            else
            {
                this.verboseInfo(funcName(), '"Never" substitution not found');
                
                // Check 4
                METSalesItemSubstitute itemSub;

                itemSub = this.findSalesItemSubstitute(
                    salesLine.ItemId,
                    METSalesItemSubstitutionCode::Replacement);

                if(!itemSub)
                {
                    this.verboseInfo(funcName(), '"Replacement" substitute not found');
                    itemSub = this.findSalesItemSubstitute(
                        salesLine.ItemId,
                        METSalesItemSubstitutionCode::OutOfStock);
                }
                
                if(itemSub)
                {
                    this.verboseInfo(funcName(), strFmt('Replacement / Out of stock substitute found (%1)',
                        itemSub.description()));                   

                    Qty replacementItemOnHand = this.queryOnHandQty(
                        itemSub.SubstituteItemID, 
                        inventDim);
                   
                    // Assuming same inventory unit.. (EA) TODO confirm, what if different and no conversion?                    
                    if(replacementItemOnHand >= salesLine.QtyOrdered)
                    {
                        this.verboseInfo(funcName(), 'Replacement item on-hand is sufficient for ordered quantity');
                        this.updateSalesLineFromSalesItemSubstitute(itemSub);

                        itemReplaced = true;
                    }
                    else
                    {
                        this.verboseInfo(funcName(), 'Replacement item on-hand is not sufficient for ordered quantity');

                        // Check 6 - *** Spec refers to InventTransID = null but
                        // this will never be the case.

                        // Check 7
                        if(itemSub.OrderOriginalItem)
                        {
                            this.verboseInfo(funcName(), 'Order original item set on substitute entry');
                            // "Order original item" applies. Do not replace item but mark
                            // sub details on line.
                            metSalesLine.SubstituteReplacementItemID    = itemSub.SubstituteItemId;
                            metSalesLine.SubstitutionCode               = itemSub.SubstitutionCode;

                            itemReplaced = false;
                        }
                        else
                        {
                            this.verboseInfo(funcName(), 'Order original item is not set on substitute entry');
                            this.updateSalesLineFromSalesItemSubstitute(itemSub);
                            this.copyToNewLine(itemSub.SubstituteItemId);
                            
                            itemReplaced = true;
                        }                        
                    }
                }
                else
                {
                    this.verboseInfo(funcName(), 'No "Replacement" or "Out of stock" substitutions found');
                    metSalesLine.SubstitutionCode = METSalesItemSubstitutionCode::OutOfStock;   // ** Confirm..
                }                
            }
        }
        else
        {
            // Enough stock of ordered item. No further action required.
            this.verboseInfo(funcName(), strFmt('On-hand qty of %1 is sufficient for ordered quantity of %2',
                onHandQty,
                salesLine.QtyOrdered));            
        }

        if(!bufCmp(salesLine, salesLine.orig()))
            salesLine.update();

        if(!bufCmp(metSalesLine,  metSalesLine.orig()))
            metSalesLine.update();

        return ret;
    }

    /// <summary>
    /// Copy sales line to new line with specified item id.
    /// </summary>
    /// <param name = "_newItemId">_newItemId</param>
    /// <returns>New sales order line</returns>
    protected SalesLine copyToNewLine(ItemId _newItemId)
    {
        this.verboseInfo(funcName(), strFmt('Copying to new line with item %1',
            _newItemId));

        SalesLine newLine;

        this.updateQuantity();

        newLine.initFromSalesTable(salesTable);
        newLine.initFromSalesLine(salesLine, true, true, true);
        newLine.ItemId = _newItemId;        
        newLine.itemIdChanged();

        newLine.insert();

        METSalesLine metNewLine = metSalesLine.data();
        metNewLine.SalesLine = newLine.RecId;
        metNewLine.insert();

        guid logReference;
        metSalesLine.SubstitutionVerboseLogReference = logReference;  
        metSalesLine.update();
        
        this.verboseInfo(funcName(), strFmt('Order line (Item %1, Lot ID %2) has been copied and replaced by (Item %3, Lot ID %4)',
            salesLine.ItemId,
            salesLine.InventTransId,
            newLine.ItemId,
            newLine.InventTransId));
        
        salesLine.delete();   

        salesLine       = newLine;
        inventDim       = salesLine.inventDim();
        metSalesLine    = metNewLine;

        return newLine;
    }

    /// <summary>
    /// Find on-hand quantity for specified item
    /// </summary>
    /// <param name = "_itemID">_itemID</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <returns>On-hand quantity</returns>
    protected Qty queryOnHandQty(ItemId _itemID, InventDim _inventDim)
    {
        InventDimParm   onHandDimParm;
        onHandDimParm.initFromInventDim(inventDim);
        InventOnhand    onHand = InventOnhand::newItemDim(_itemId, _inventDim, onHandDimParm);
        Qty             onHandQty;
        boolean         checkTestOnHandQtyTable = true; // **** This is temporary, for testing/debugging only

        this.verboseInfo(funcName(), strFmt('Checking on-hand for item %1',
            _itemID));
         
        if(checkTestOnHandQtyTable)
        {
            METSalesItemSubstituteTestOnHand testOnHand = METSalesItemSubstituteTestOnHand::find(
                _inventDim.InventSiteId, 
                _itemID);
            if(testOnHand)
            {
                str msg = strFmt('** Using testing on-hand quantity of %1 for %2-%3',
                    testOnHand.QtyOnHand,
                    _itemID,
                    _inventDim.InventSiteId);
                this.verboseInfo(funcName(), msg);
                warning(msg);

                return testOnHand.QtyOnHand;
            }
        }

        if(CustParameters::find().METSubstitutionIncludeOnOrderInventory)
        {
            onHandQty = onHand.availOrdered(true);
            this.verboseInfo(funcName(), strFmt('On-hand quantity including on-order is %1',
                onHandQty));
        }
        else
        {
            onHandQty = onHand.availPhysical();
            this.verboseInfo(funcName(), strFmt('On-hand quantity (physical only) is %1',
                onHandQty));
        }
        return onHandQty;
    }

    /// <summary>
    /// Perform substitution checks/updates at point of order line entry. Relates to
    /// the "Always" substitution code or a "Parent/child" relationship.
    /// </summary>    
    /// <returns>Validation result</returns>
    protected boolean checkSalesLineAtCreation()
    {
        boolean                                 ret = true;

        METSalesItemSubstitute                  itemSub;
        METSalesItemSubstitutionParentChild     parentChild;
        
        select firstonly parentChild
            where   parentChild.InventSiteId    == salesTable.InventSiteId
            &&      parentChild.ChildItemID     == salesLine.ItemId;

        if(parentChild)
        {
            this.verboseInfo(funcName(), strFmt('Parent/child relationship exists for child item %1 (Parent item %2)',
                parentChild.ChildItemID,
                parentChild.ParentItemID));            

            if(this.yesNoPrompt(strFmt("Replace child item number %1 with Parent item number %2?",
                parentChild.ChildItemID,
                parentChild.ParentItemID)))
            {
                salesLine.ItemId                            = parentChild.ParentItemID;
                metSalesLine.SubstituteOriginalItemID       = parentChild.ChildItemID;
                metSalesLine.SubstituteReplacementItemID    = parentChild.ParentItemID;
                metSalesLine.SubstituteParentItemID         = parentChild.ParentItemID; // *** Needed separately?
                metSalesLine.SubstitutionType               = METSalesItemSubstitutionType::ParentChild;
                metSalesLine.SubstitutionCode               = METSalesItemSubstitutionCode::None;
                metSalesLine.SubstitutionSetupRefRecID      = parentChild.RecId;

                itemReplaced = true;                                
            }
            else
            {
                // Prompted for replacement based on parent/child but user cancelled updated.
                ret = checkFailed(strfmt("Item %1 cannot be selected as it has a parent/child substitution defined.", salesLine.ItemId));
            }
        }
        else
        {
            this.verboseInfo(funcName(), strFmt('No Parent/child relationship exists for item %1', salesLine.ItemId));

            itemSub = this.findSalesItemSubstitute(
                salesLine.ItemId, 
                METSalesItemSubstitutionCode::Always);

            if(itemSub)
            {
                this.verboseInfo(funcName(), strFmt('"Always" item substitution exists for item %1', salesLine.ItemId));

                if(this.yesNoPrompt(strFmt("Replace ordered item number %1 with substitute item number %2?",
                    itemSub.ItemId,
                    itemSub.SubstituteItemId)))
                {
                    this.updateSalesLineFromSalesItemSubstitute(itemSub);
                    itemReplaced = true;                    
                }
                else
                {
                    // Prompted for replacement based on 'Always' substitution but user did not confirm.
                    ret = checkFailed(strFmt("%1 cannot be selected as it has a substitution in place", salesLine.ItemId));
                }
            }
            else
            {
                this.verboseInfo(funcName(), 'No matching substitute found with "Always" code');
            }
        }
        return ret;
    }

    /// <summary>
    /// Find valid item substitute for specified item/code
    /// </summary>
    /// <param name = "_itemID">_itemID</param>
    /// <param name = "_subCode">_subCode</param>
    /// <returns>Matching entry or null</returns>
    protected METSalesItemSubstitute findSalesItemSubstitute(
        ItemId                              _itemID,
        METSalesItemSubstitutionCode        _subCode)  
    {
        this.verboseInfo(funcName(), strFmt('Searching for substitute for item %1 (%2)',
            _itemID,
            _subCode));

        METSalesItemSubstitute itemSub;
        select firstonly itemSub
            order by AccountCode asc
            where   itemSub.ItemId              == _itemID
            &&      itemSub.InventSiteId        == salesTable.InventSiteId
            &&      itemSub.SubstitutionCode    == _subCode
            &&  (   // table/group/all match
                (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::Table &&
                    itemSub.AccountRelation == salesTable.CustAccount)
            ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::GroupId &&
                    itemSub.AccountRelation == substitutionGroup)
            ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::All &&
                    itemSub.AccountRelation == '')
            );
        return itemSub;
    }

/// <summary>
/// Update substitute fields on sales line buffer
/// </summary>
/// <param name = "_itemSub">_itemSub</param>
/// <param name = "_setSalesLineItemID">_setSalesLineItemID</param>
protected void updateSalesLineFromSalesItemSubstitute(
    METSalesItemSubstitute          _itemSub,
    boolean                         _setSalesLineItemID = true)
{
    if(_setSalesLineItemID)
    {
        salesLine.ItemId = _itemSub.SubstituteItemId;
    }
    metSalesLine.SubstituteOriginalItemID        = _itemSub.ItemId;
    metSalesLine.SubstituteReplacementItemID     = _itemSub.SubstituteItemId;
    metSalesLine.SubstituteParentItemID          = '';
    metSalesLine.SubstitutionType                = METSalesItemSubstitutionType::SubstitutionCode;
    metSalesLine.SubstitutionCode                = _itemSub.SubstitutionCode;
    metSalesLine.SubstitutionSetupRefRecID       = _itemSub.RecId;
}

    /// <summary>
    /// Check and update quantity/unit if required.
    /// </summary>
    /// <returns>Validation result</returns>
    protected boolean updateQuantity()
    {
        boolean             ret                     = true;
        InventTable         originalItem            = InventTable::find(metSalesLine.SubstituteOriginalItemID);
        InventTableModule   originalItemInvent      = originalItem.inventTableModuleInvent();
        InventTable         replacementItem         = InventTable::find(metSalesLine.SubstituteReplacementItemID);
        InventTableModule   replacementItemInvent   = replacementItem.inventTableModuleInvent();    
        InventTableModule   replacementItemSales    = replacementItem.inventTableModuleSales();

        this.verboseInfo(funcName(), strFmt('Original %1 item ordered quantity %2 of sales unit %3',
            originalItem.ItemId,
            salesLine.SalesQty,
            salesLine.SalesUnit));

        this.verboseInfo(funcName(), strFmt('Original %1 item ordered quantity %2 of inventory unit %3',
            originalItem.ItemId,
            salesLine.QtyOrdered,
            originalItemInvent.UnitId));

        this.verboseInfo(funcName(), strFmt('Replacement item %1 has inventory unit %2, sales unit %3',
            replacementItem.ItemId,
            replacementItemInvent.UnitId,
            replacementItemSales.UnitId));

        if(originalItemInvent.UnitId == replacementItemInvent.UnitID)
        {
            Qty replacementQty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                replacementItem.ItemId,
                InventDim::findOrCreate(inventDim).inventDimId,
                salesLine.QtyOrdered,
                replacementItemInvent.UnitId,
                replacementItemSales.UnitId,
                true,
                true);

            salesLine.SalesQty  = replacementQty;
            salesLine.SalesUnit = replacementItemSales.UnitId;  
          
            SalesLine::modifySalesQty(salesLine, inventDim);

            this.verboseInfo(funcName(), strFmt('Conversion to %1 (%2) sales quantity',
                salesLine.SalesQty,
                salesLine.SalesUnit));
            this.verboseInfo(funcName(), strFmt('Inventory quantity updated to %1 (%2)',
                salesLine.QtyOrdered,
                replacementItemInvent.UnitId));
        }
        else
        {
            // How to handle this scenario? (Item A and B don't have common inventory unit).
            this.verboseInfo(funcName(), strFmt('Item %1 and %2 have different inventory units (%3 and %4). Unable to convert.',
                originalItem.ItemId,
                replacementItem.ItemId,
                originalItemInvent.UnitId,
                replacementItemInvent.UnitId));
            ret = false;
        }
        return ret;       
    }

    /// <summary>
    /// Add verbose info to the log.
    /// </summary>
    /// <param name = "_func">_func</param>
    /// <param name = "_msg">_msg</param>
    private void verboseInfo(str _func, str _msg)
    {
        if(this.verboseLogging)
        {
            METSalesItemSubstitutionVerboseLog  verboseLog;

            verboseLog.SalesId          = salesTable.SalesId;
            verboseLog.EventSource      = this.eventSource;
            verboseLog.Message          = _msg;
            verboseLog.Function         = subStr(_func, strFind(_func, '.', 1, 999) + 1, 999);
            verboseLog.LogReference     = metSalesLine.SubstitutionVerboseLogReference;

            if(this.verboseLogConnection)
            {
                verboseLog.setConnection(this.verboseLogConnection);
            }
            verboseLog.insert();
        }
    }

/// <summary>
/// Prompt message with yes/no confirmation. If non-interactive, assume a 'Yes'
/// response. (eg via backend service/batch).
/// </summary>
/// <param name = "_msg">_msg</param>
/// <returns>Result</returns>
protected boolean yesNoPrompt(str _msg)
{
    if(interactive)
    {
        boolean promptRet = (Box::yesNo(_msg, DialogButton::No) == DialogButton::Yes);
        this.verboseInfo(funcName(), promptRet ?
            'User confirmed replacement' :
            'User cancelled replacement');
        return promptRet;
    }
    else
    {
        this.verboseInfo(funcName(), 'Replacement accepted without prompt (non-interactive)');
        return true;
    }
}

/// <summary>
/// Constructor
/// </summary>
/// <param name = "_salesLine">_salesLine</param>
/// <param name = "_metSalesLine">_metSalesLine</param>
/// <param name = "_inventDim">_inventDim</param>
protected void new(
    SalesLine       _salesLine,
    METSalesLine    _metSalesLine,
    InventDim       _inventDim)
{
    salesLine       = _salesLine;
    metSalesLine    = _metSalesLine;
    inventDim       = _inventDim;
    salesTable      = salesLine.salesTable();
}

    /// <summary>
    /// construct
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <param name = "_metSalesLine">_metSalesLine</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <param name = "_eventSource">_eventSource</param>
    /// <param name = "_interactive">_interactive</param>
    /// <returns>New instance</returns>
    static public METSalesItemSubstitution construct(
        SalesLine                               _salesLine,
        METSalesLine                            _metSalesLine,
        InventDim                               _inventDim,
        METSalesItemSubstitutionEventSource     _eventSource,
        boolean                                 _interactive = true)
    {
        METSalesItemSubstitution sub = new METSalesItemSubstitution(
            _salesLine,
            _metSalesLine,
            _inventDim);
    
        sub.eventSource     = _eventSource;
        sub.interactive     = _interactive;

        return sub;
    }
